{
  "returncode": 0,
  "output": "// Quizzy's little bits of behaviour.

// The "Active" checkbox on the quiz page saves at once, without a button.
document.addEventListener("change", (event) => {
  const input = event.target
  if (!(input instanceof HTMLInputElement) || !input.matches("[data-auto-submit]")) return
  if (input.form) input.form.requestSubmit()
})

// The option rows of the question form.
document.addEventListener("click", (event) => {
  const add = event.target.closest("[data-add-option]")
  if (add) {
    event.preventDefault()
    addOptionRow(add)
    return
  }

  const remove = event.target.closest("[data-remove-option]")
  if (remove) {
    event.preventDefault()
    const row = remove.closest("[data-option-row]")
    if (row) row.remove()
    syncOptionRows()
  }
})

function optionRowsContainer(from) {
  const form = from.closest("form")
  return form ? form.querySelector("[data-option-rows]") : null
}

function addOptionRow(button) {
  const container = optionRowsContainer(button)
  if (!container) return

  const row = document.createElement("div")
  row.className = "option-row"
  row.setAttribute("data-option-row", "")
  row.innerHTML = [
    '<div class="option-row__text">',
    '  <label class="field-label"></label>',
    '  <input class="input" type="text" placeholder="Option text">',
    "</div>",
    '<label class="checkbox">',
    '  <input type="checkbox" value="1">',
    "  <span></span>",
    "</label>",
    '<button type="button" class="btn btn--danger btn--icon" data-remove-option aria-label="">&#10005;</button>'
  ].join("\n")
  container.appendChild(row)
  syncOptionRows()

  const input = row.querySelector("input[type='text']")
  if (input) input.focus()
}

// Keeps the numbers in the labels and the field names in step with the rows.
function syncOptionRows() {
  document.querySelectorAll("[data-option-rows]").forEach((container) => {
    container.querySelectorAll("[data-option-row]").forEach((row, index) => {
      const number = index + 1
      const text = row.querySelector("input[type='text']")
      const check = row.querySelector("input[type='checkbox']")
      const textLabel = row.querySelector("label.field-label")
      const checkLabel = row.querySelector("label.checkbox")
      const remove = row.querySelector("[data-remove-option]")

      if (textLabel) textLabel.textContent = `Option ${number}`
      if (checkLabel) {
        const caption = checkLabel.querySelector("span")
        if (caption) caption.textContent = `Option ${number} is correct`
      }

      if (text) {
        text.id = `question_options_${index}_text`
        text.name = `question[options][${index}][text]`
        if (textLabel) textLabel.setAttribute("for", text.id)
      }

      if (check) {
        check.id = `question_options_${index}_correct`
        check.name = `question[options][${index}][correct]`
        if (checkLabel) checkLabel.setAttribute("for", check.id)
      }

      if (remove) remove.setAttribute("aria-label", `Remove option ${number}`)
    })
  })
}
#!/usr/bin/env bash
#
# Quizzy: prepare everything the app needs and serve it in production mode,
# in the foreground, on all interfaces on PORT.

set -euo pipefail

cd "$(dirname "$0")/.."

export RAILS_ENV="${RAILS_ENV:-production}"
export RAILS_LOG_LEVEL="${RAILS_LOG_LEVEL:-info}"
export PORT="${PORT:-3000}"

# The app runs on plain HTTP, without a reverse proxy.
export ASSUME_SSL=false
export FORCE_SSL=false

if [ -z "${SECRET_KEY_BASE:-}" ]; then
  SECRET_KEY_BASE="$(bin/rails secret)"
  export SECRET_KEY_BASE
fi

mkdir -p storage log tmp/pids

# The database lives under storage/.
bin/rails db:prepare

# Stylesheets, the font and the JavaScript, digest stamped under public/assets.
bin/rails assets:precompile

exec bin/rails server --binding 0.0.0.0 --port "$PORT"
# Pin npm packages by running ./bin/importmap

pin "application"
pin "quizzy" # our own little bit of behaviour
pin "@hotwired/turbo-rails", to: "turbo.min.js"
pin "@hotwired/stimulus", to: "stimulus.min.js"
pin "@hotwired/stimulus-loading", to: "stimulus-loading.js"
pin_all_from "app/javascript/controllers", under: "controllers"
require "active_support/core_ext/integer/time"

Rails.application.configure do
  # Settings specified here will take precedence over those in config/application.rb.

  # Code is not reloaded between requests.
  config.enable_reloading = false

  # Eager load code on boot for better performance and memory savings (ignored by Rake tasks).
  config.eager_load = true

  # Full error reports are disabled.
  config.consider_all_requests_local = false

  # Turn on fragment caching in view templates.
  config.action_controller.perform_caching = true

  # Cache assets for far-future expiry since they are all digest stamped.
  config.public_file_server.headers = { "cache-control" => "public, max-age=#{1.year.to_i}" }

  # Enable serving of images, stylesheets, and JavaScripts from an asset server.
  # config.asset_host = "http://assets.example.com"

  # Store uploaded files on the local file system (see config/storage.yml for options).
  config.active_storage.service = :local

  # Assume all access to the app is happening through a SSL-terminating reverse proxy.
  # config.assume_ssl = true

  # Force all access to the app over SSL, use Strict-Transport-Security, and use secure cookies.
  # config.force_ssl = true

  # Skip http-to-https redirect for the default health check endpoint.
  # config.ssl_options = { redirect: { exclude: ->(request) { request.path == "/up" } } }

  # Log to STDOUT with the current request id as a default log tag.
  config.log_tags = [ :request_id ]
  config.logger   = ActiveSupport::TaggedLogging.logger(STDOUT)

  # Change to "debug" to log everything (including potentially personally-identifiable information!).
  config.log_level = ENV.fetch("RAILS_LOG_LEVEL", "info")

  # Prevent health checks from clogging up the logs.
  config.silence_healthcheck_path = "/up"

  # Don't log any deprecations.
  config.active_support.report_deprecations = false

  # Replace the default in-process memory cache store with a durable alternative.
  # config.cache_store = :mem_cache_store

  # Replace the default in-process and non-durable queuing backend for Active Job.
  # config.active_job.queue_adapter = :resque

  # Enable locale fallbacks for I18n (makes lookups for any locale fall back to
  # the I18n.default_locale when a translation cannot be found).
  config.i18n.fallbacks = true

  # Do not dump schema after migrations.
  config.active_record.dump_schema_after_migration = false

  # Only use :id for inspections in production.
  config.active_record.attributes_for_inspect = [ :id ]

  # Enable DNS rebinding protection and other `Host` header attacks.
  # config.hosts = [
  #   "example.com",     # Allow requests from example.com
  #   /.*\.example\.com/ # Allow requests from subdomains like `www.example.com`
  # ]
  #
  # Skip DNS rebinding protection for the default health check endpoint.
  # config.host_authorization = { exclude: ->(request) { request.path == "/up" } }
  # Quizzy is served over plain HTTP, straight from this process, with any host name.
  config.assume_ssl = false
  config.force_ssl  = false
  config.hosts      = []
end
"
}

